-- အရင်ရှိပြီးသား Table အဟောင်းရှိပါက ဖျက်ပစ်မည် (Error မတက်စေရန်)
DROP TABLE IF EXISTS n4_vocabulary;

-- Column ၇ ခုပါဝင်သော Table အသစ် ပြန်လည်တည်ဆောက်မည်
CREATE TABLE n4_vocabulary (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    chapter INTEGER,
    kana TEXT,
    kanji TEXT,
    meaning TEXT,
    part_of_speech TEXT,
    note TEXT,
    example TEXT
);

COMMIT;
